def connect(root):
    head = root
    while head is not None:
        dummy = tail = TreeNode(0)
        node = head
        while node is not None:
            for child in (node.left, node.right):
                if child is not None:
                    tail.next = child
                    tail = child
            node = node.next
        head = dummy.next                 # first node of the level below
    return root
